        //   - Multiple endFlow instances can exist at different nesting levels
        //
        // What This Test Validates:
        //   1. Flow structure with nested forEach and if statements
        //   2. endFlow records with correct logic_definition
        //   3. parent_ui_id linking endFlow to parent if statement
        //   4. Multiple endFlow instances at different nesting levels
        //   5. Proper order field for execution sequence
        // ========================================================================
        test('endFlow flow logic transforms correctly', async () => {
            // Step 1: Transform Fluent file to XML and get merged records
            const merged = await getMergedRecordUpdates(ctx.createProject(), 'end-flow.now.ts', 'flow-logics/fluent')

            // Step 2: Verify flow record structure
            expect(merged['sys_hub_flow']).toBeDefined()
            const flowRecords = merged['sys_hub_flow']
            expect(flowRecords.length).toBe(1)

            const flow = flowRecords[0]
            expect(flow.name).toBe('Test-End-Flow-Flow-Logic')
            expect(flow.type).toBe('flow')

            // Step 3: Verify trigger configuration
            expect(merged['sys_hub_trigger_instance_v2']).toBeDefined()
            const triggers = merged['sys_hub_trigger_instance_v2']
            expect(triggers.length).toBe(1)
            expect(triggers[0].name).toBe('Created')

            // Step 4: Verify flow logic instances
            // This flow has: forEach loops, if statements, and endFlow instances
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogics = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogics.length).toBeGreaterThan(0)

            // Step 5: Verify structure by checking comments (annotations)
            // Find endFlow instances by comment
            const endFlowInstances = flowLogics.filter((logic: any) => {
                return logic.comment && logic.comment.toLowerCase().includes('end flow')
            })
            expect(endFlowInstances.length).toBeGreaterThan(0)

            // Step 6: Verify endFlow has parent_ui_id (nested inside if)
            const nestedEndFlow = endFlowInstances.find((logic: any) => {
                return logic.parent_ui_id && logic.parent_ui_id !== ''
            })
            expect(nestedEndFlow).toBeDefined()
            expect(nestedEndFlow.parent_ui_id).toBeTruthy()

            // Step 7: Verify forEach loops exist (by comment)
            const forEachInstances = flowLogics.filter((logic: any) => {
                return logic.comment && logic.comment.toLowerCase().includes('iterate')
            })
            expect(forEachInstances.length).toBeGreaterThan(0)

            // Step 8: Verify if statements exist (by comment containing 'check')
            const ifInstances = flowLogics.filter((logic: any) => {
                return logic.comment && logic.comment.toLowerCase().includes('check')
            })
            expect(ifInstances.length).toBeGreaterThan(0)

            // Step 9: Verify nested structure - some forEach should have parent_ui_id
            const nestedForEach = forEachInstances.find((forEach: any) => {
                return forEach.parent_ui_id && forEach.parent_ui_id !== ''
            })
            expect(nestedForEach).toBeDefined()

            // Step 10: Verify order field exists and is sequential
            flowLogics.forEach((logic: any) => {
                expect(logic.order).toBeDefined()
                expect(typeof logic.order).toBe('number')
            })

            // Step 11: Verify ui_id exists for all flow logic
            flowLogics.forEach((logic: any) => {
                expect(logic.ui_id).toBeDefined()
                expect(logic.ui_id).toMatch(/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/)
            })
        })

