            expect(flowRecords.length).toBe(1)
            expect(flowRecords[0].name).toBe('Test-Skip-Iteration-Flow-Logic')

            // Verify flow logic instances
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogics = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogics.length).toBeGreaterThan(0)

            // Find skipIteration instances by comment
